using Aspire.Hosting.Testing;
using Microsoft.Extensions.AI;
using Microsoft.Extensions.AI.Evaluation;
using Microsoft.Extensions.AI.Evaluation.Quality;
using Microsoft.Extensions.AI.Evaluation.Reporting;
using Microsoft.Extensions.DependencyInjection;

namespace MyApp.Evaluation;

[TestClass]
public class EvaluationTests
{
    private static ReportingConfiguration? s_reportingConfiguration;

    [ClassInitialize]
    public static void Initialize(TestContext context)
    {
        s_reportingConfiguration = CreateReportingConfiguration();
    }

    [TestMethod]
    public async Task ChatResponse_IsRelevant()
    {
        await using var scenario =
            await s_reportingConfiguration!.CreateScenarioRunAsync(nameof(ChatResponse_IsRelevant));

        var chatClient = await CreateChatClientAsync();

        var messages = new List<ChatMessage>
        {
            new(ChatRole.User, "What is the capital of France?")
        };

        var response = await chatClient.GetResponseAsync(messages);
        messages.Add(response.Message);

        await scenario.EvaluateAsync(messages);
    }

    [TestMethod]
    public async Task ChatResponse_IsGrounded()
    {
        await using var scenario =
            await s_reportingConfiguration!.CreateScenarioRunAsync(nameof(ChatResponse_IsGrounded));

        var chatClient = await CreateChatClientAsync();

        var context = "Paris is the capital city of France. It is located in northern France.";
        var messages = new List<ChatMessage>
        {
            new(ChatRole.User, $"Based on the following context, what is the capital of France?\n\nContext: {context}")
        };

        var response = await chatClient.GetResponseAsync(messages);
        messages.Add(response.Message);

        await scenario.EvaluateAsync(
            messages,
            additionalContext: [new EvaluationContext("grounding", context)]);
    }

    private static ReportingConfiguration CreateReportingConfiguration()
    {
        var evaluators = new IEvaluator[]
        {
            new RelevanceEvaluator(),
            new CoherenceEvaluator(),
            new FluencyEvaluator(),
            new GroundednessEvaluator()
        };

        return DiskBasedReportingConfiguration.Create(
            storageRootPath: Path.Combine(Path.GetTempPath(), "MyApp.Evaluation"),
            evaluators: evaluators,
            chatConfiguration: new ChatConfiguration(chatClientFactory: CreateChatClientAsync));
    }

    private static async Task<IChatClient> CreateChatClientAsync()
    {
        var appHost =
            await DistributedApplicationTestingBuilder.CreateAsync<Projects.MyApp_AppHost>();

        var app = await appHost.BuildAsync();
        await app.StartAsync();

        return app.Services.GetRequiredService<IChatClient>();
    }
}

